  `total_devices` int(11) DEFAULT 15,
  `online_devices` int(11) DEFAULT 0,
  `offline_devices` int(11) DEFAULT 15,
  `warning_devices` int(11) DEFAULT 0,
  `availability_percent` decimal(5,2) DEFAULT 0.00,
  `troubled_devices` text DEFAULT NULL,
  `recommendation` longtext DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `created_by` varchar(100) DEFAULT 'System Integration (Shift 2)',
