DROP TABLE IF EXISTS `monitoring_daily_stats`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `monitoring_daily_stats` (
  `stat_id` int(11) NOT NULL AUTO_INCREMENT,
  `stat_date` date NOT NULL,
  `asset_id` int(11) NOT NULL,
  `total_online` int(11) DEFAULT 0,
  `total_offline` int(11) DEFAULT 0,
  `total_warning` int(11) DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`stat_id`),
  UNIQUE KEY `uq_date_asset` (`stat_date`,`asset_id`),
  KEY `asset_id` (`asset_id`),
  CONSTRAINT `fk_daily_stats_assets` FOREIGN KEY (`asset_id`) REFERENCES `assets` (`asset_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

