LOCK TABLES `monitoring_daily_stats` WRITE;
/*!40000 ALTER TABLE `monitoring_daily_stats` DISABLE KEYS */;
/*!40000 ALTER TABLE `monitoring_daily_stats` ENABLE KEYS */;
UNLOCK TABLES;

--
